/* AppAdminSafetyMapper.countUserSiteAuth */
SELECT
    COUNT(1)
FROM TB_USER_SITE_AUTH A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'

/* AppAdminSafetyMapper.selectRiskFindingList */
SELECT


WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}

    AND A.ASSESSMENT_STATUS = #{assessmentStatus}


    AND A.PROCESS_CD = #{processCd}


    AND A.RISK_TYPE_CD = #{riskTypeCd}

/* 최신순(입력일시 내림차순) — 동일 시각은 평가코드(채번 역순)로 안정 정렬, 최신이 위로 */
ORDER BY A.INSERT_DATE DESC, A.ASSESSMENT_CD DESC

/* AppAdminSafetyMapper.selectRiskFindingDetail */
SELECT


WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.PROCESS_CD = #{processCd}
  AND A.ASSESSMENT_CD = #{assessmentCd}

/* AppAdminSafetyMapper.selectRiskFindingMeta */
SELECT
    A.CMPNY_CD          AS cmpnyCd
  , A.SITE_CD           AS siteCd
  , A.PROCESS_CD        AS processCd
  , A.ASSESSMENT_CD     AS assessmentCd
  , A.ASSESSMENT_STATUS AS assessmentStatus
FROM TB_RISK_ASSESSMENT A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.PROCESS_CD = #{processCd}
  AND A.ASSESSMENT_CD = #{assessmentCd}

mapper.update:
/* AppAdminSafetyMapper.updateRiskStatus */
UPDATE TB_RISK_ASSESSMENT
SET
    ASSESSMENT_STATUS = #{targetStatus}

  , REVAL_DATE        = REPLACE(#{revalDate}, '-', '')
  , REVAL_BEFORE_DESC = #{revalBeforeDesc}
  , REVAL_ASSESSOR_ID = #{gvUserCd}
  , REVAL_ASSESS_DATE = NOW()

  , UPDATE_NO         = #{gvUserCd}
  , UPDATE_DATE       = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PROCESS_CD = #{processCd}
  AND ASSESSMENT_CD = #{assessmentCd}
  AND ASSESSMENT_STATUS = #{expectedCurrent}
